using System.Collections.ObjectModel;
using System.IO;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Interop;
using Microsoft.Win32;
namespace FieldTrader;
public partial class VoiceBoardWindow : Window,IDisposable {
 [DllImport("user32.dll",SetLastError=true)] private static extern bool RegisterHotKey(IntPtr h,int id,uint mods,uint key);
 [DllImport("user32.dll")] private static extern bool UnregisterHotKey(IntPtr h,int id);
 private readonly string root;private readonly VoiceBoardSettings settings;private readonly ObservableCollection<VoicePhrase> phrases;
 private readonly VoicePlaybackController playback;private readonly VoiceMicrophoneMixer microphone=new();private readonly System.Windows.Threading.DispatcherTimer micTimer=new(){Interval=TimeSpan.FromMilliseconds(80)};
 private VoiceBoardAudio? audio;private HwndSource? source;private readonly Dictionary<int,VoicePhrase> hotkeys=[];private bool disposed,ready;
 internal VoiceBoardWindow(string root){InitializeComponent();this.root=root;playback=new(new WindowsVoiceKeyInput(),WindowsVoiceKeyInput.GameIsForeground,()=>{try{audio?.Stop();}finally{microphone.StopClip();}});settings=VoiceBoardSettings.Load(root,out var notice);phrases=new(settings.Phrases);var view=System.Windows.Data.CollectionViewSource.GetDefaultView(phrases);view.Filter=item=>item is VoicePhrase p&&(ShowType.SelectedIndex==0||(ShowType.SelectedIndex==1?!string.IsNullOrWhiteSpace(p.Wav):string.IsNullOrWhiteSpace(p.Wav)));PhraseGrid.ItemsSource=view;ShowType.SelectionChanged+=(_,_)=>{Commit();view.Refresh();};VolumeSlider.Value=settings.Volume;RateSlider.Value=settings.Rate;TalkMode.SelectedIndex=settings.PushToTalk?0:1;TalkKeyBox.Text=settings.TalkKey;TalkKeyBox.IsEnabled=settings.PushToTalk;TalkMode.SelectionChanged+=(_,_)=>{TalkKeyBox.IsEnabled=TalkMode.SelectedIndex==0;if(ready)Guard(()=>{playback.Stop();StatusText.Text="发言模式已切换。";});};TransmitBoost.Value=settings.TransmitBoost;TransmitBoost.ValueChanged+=(_,_)=>microphone.TransmitGain=(float)TransmitBoost.Value;VolumeSlider.ValueChanged+=(_,_)=>{microphone.EffectGain=(float)VolumeSlider.Value/100;Guard(()=>audio?.SetLiveVolume((int)VolumeSlider.Value));};MicrophoneVolume.Value=settings.MicrophoneVolume;MicrophoneVolume.ValueChanged+=(_,_)=>microphone.MicrophoneGain=(float)MicrophoneVolume.Value/100;micTimer.Tick+=(_,_)=>{float peak=microphone.OutputPeak;MicrophoneMeter.Value=peak;SendLevel.Text=peak>0?$"{20*Math.Log10(peak):0} dBFS":"静音";};microphone.Faulted+=(generation,message)=>Dispatcher.BeginInvoke(new Action(()=>{if(disposed||!microphone.IsRunning||generation!=microphone.Generation)return;StopMicrophoneMix();MixStatus.Text="混音已停止："+message;}));
  MicrophoneBox.SelectionChanged+=(_,_)=>{if(microphone.IsRunning)StopMicrophoneMix();};MixOutputBox.SelectionChanged+=(_,_)=>{if(microphone.IsRunning)StopMicrophoneMix();};StatusText.Text=notice;SourceInitialized+=(_,_)=>{source=HwndSource.FromHwnd(new WindowInteropHelper(this).Handle);source.AddHook(Hook);};Loaded+=(_,_)=>{if(ready)return;ready=true;RefreshAudio();RefreshMixDevices();ApplyHotkeys();var first=phrases.FirstOrDefault(p=>!string.IsNullOrWhiteSpace(p.Wav));if(first!=null){PhraseGrid.SelectedItem=first;PhraseGrid.ScrollIntoView(first);}};OutputBox.SelectionChanged+=(_,_)=>{try{playback.Stop();}catch(Exception ex){StatusText.Text=ex.Message;}};HotkeysEnabled.Click+=(_,_)=>ApplyHotkeys();Closing+=(_,e)=>{if(disposed)return;e.Cancel=true;try{Save();Hide();StatusText.Text=microphone.IsRunning?"窗口已隐藏，真人麦克风混音与快捷键仍在运行。":"窗口已隐藏，快捷键仍可使用。";}catch(Exception ex){StatusText.Text="保存失败："+ex.Message;}};}
 private void Commit(){}
 private VoicePhrase? Selected=>PhraseGrid.SelectedItem as VoicePhrase;
 private void Guard(Action action){try{action();}catch(Exception ex){StatusText.Text="操作失败："+ex.Message;}}
 private void RefreshAudio(){Guard(()=>{StopMicrophoneMix();playback.Stop();string output=(OutputBox.SelectedItem as SpeechChoice)?.Id??settings.OutputId;string voice=(VoiceBox.SelectedItem as SpeechChoice)?.Id??settings.VoiceId;OutputBox.ItemsSource=null;VoiceBox.ItemsSource=null;if(audio==null)audio=new();else audio.Refresh();OutputBox.ItemsSource=audio.Outputs;VoiceBox.ItemsSource=audio.Voices;OutputBox.SelectedItem=audio.Outputs.FirstOrDefault(o=>o.Id==output);VoiceBox.SelectedItem=audio.Voices.FirstOrDefault(v=>v.Id==voice)??(string.IsNullOrEmpty(voice)?audio.Voices.FirstOrDefault(v=>v.Chinese)??audio.Voices.FirstOrDefault():null);StatusText.Text=OutputBox.SelectedItem==null?"请先选择播放设备；首次或设备断开后不会自动改用其他输出。":"设备已更新。";});}
 private void RefreshDevices(object sender,RoutedEventArgs e){RefreshAudio();RefreshMixDevices();}
 private void RefreshMixDevices(){Guard(()=>{string mic=(MicrophoneBox.SelectedItem as AudioDevice)?.Id??settings.MicrophoneId;string target=(MixOutputBox.SelectedItem as AudioDevice)?.Id??settings.MixOutputId;MicrophoneBox.ItemsSource=VoiceMicrophoneMixer.Inputs().Where(d=>VoiceMicrophoneMixer.IsPhysicalMicrophone(d.Name)).ToArray();MixOutputBox.ItemsSource=AudioCaptureService.EnumerateDevices().Where(d=>VoiceMicrophoneMixer.IsVirtualOutput(d.Name)).ToArray();MicrophoneBox.SelectedItem=((IEnumerable<AudioDevice>)MicrophoneBox.ItemsSource).FirstOrDefault(d=>d.Id==mic)??(MicrophoneBox.Items.Count==1?MicrophoneBox.Items[0]:null);MixOutputBox.SelectedItem=((IEnumerable<AudioDevice>)MixOutputBox.ItemsSource).FirstOrDefault(d=>d.Id==target)??(MixOutputBox.Items.Count==1?MixOutputBox.Items[0]:null);MixStatus.Text=MixOutputBox.Items.Count==0?"未检测到虚拟线路 · 请点安装虚拟麦克风":"仅本地试听 · 请开启混音后再向游戏发送";});}
 private void StopMicrophoneMix(){try{playback.Stop();}finally{micTimer.Stop();microphone.Dispose();MicrophoneMeter.Value=0;SendLevel.Text="未发送";MicrophoneVolume.IsEnabled=false;TransmitBoost.IsEnabled=false;MixToggle.Content="开启麦克风混音";MixStatus.Text="仅本地试听 · 尚未向游戏发送";}}
 private void InstallCableDriver(object sender,RoutedEventArgs e){try{if(VoiceCableInstaller.IsInstalled()){RefreshMixDevices();MixStatus.Text=MixOutputBox.Items.Count>0?"已检测到VB-CABLE，请选择混音设备。":"组件已安装但设备未就绪，请重启并启用设备后刷新。";return;}StopMicrophoneMix();VoiceCableInstaller.Launch();MixStatus.Text="已打开官方安装器：点Install Driver，重启后刷新设备。";}catch(System.ComponentModel.Win32Exception ex)when(ex.NativeErrorCode==1223){MixStatus.Text="已取消组件安装；其他功能仍可使用。";}catch(Exception ex){MixStatus.Text="组件安装未启动："+ex.Message;}}
 private void OpenCableGuide(object sender,RoutedEventArgs e)=>Guard(()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://vb-audio.com/Cable/"){UseShellExecute=true}));
 private void ToggleMicrophoneMix(object sender,RoutedEventArgs e){Guard(()=>{if(microphone.IsRunning){StopMicrophoneMix();return;}if(MicrophoneBox.SelectedItem is not AudioDevice mic)throw new InvalidOperationException("请先选择你的实体麦克风。");if(MixOutputBox.SelectedItem is not AudioDevice target)throw new InvalidOperationException("请先安装并选择虚拟线路 CABLE Input，游戏麦克风选 CABLE Output。");playback.Stop();microphone.Start(mic.Id,target.Id,(float)MicrophoneVolume.Value/100);microphone.EffectGain=(float)VolumeSlider.Value/100;microphone.TransmitGain=(float)TransmitBoost.Value;MicrophoneVolume.IsEnabled=true;TransmitBoost.IsEnabled=true;micTimer.Start();MixToggle.Content="关闭麦克风混音";MixStatus.Text="正在转发真人麦克风 + 音效 · 游戏需选对应虚拟麦克风";Save();});}
 private async void Play(VoicePhrase? phrase,bool fromHotkey=false){
  if(phrase==null){StatusText.Text="请先选一条短句。";return;}
  try{Commit();if(audio==null)throw new InvalidOperationException("桌面语音服务不可用，请刷新设备。");var output=OutputBox.SelectedItem as SpeechChoice;if(!microphone.IsRunning&&output==null)throw new InvalidOperationException("请先开启麦克风混音，或选择本地试听设备。");bool auto=TalkMode.SelectedIndex==0;uint key=0x54;if(auto&&!VoicePlaybackController.ParseTalkKey(TalkKeyBox.Text,out key))throw new InvalidOperationException("说话键请填写单个字母、数字或F1～F11。");var voice=VoiceBox.SelectedItem as SpeechChoice;int volume=(int)VolumeSlider.Value,rate=(int)RateSlider.Value;
   bool mixed=microphone.IsRunning;playback.Stop();string? file=mixed?audio.FileForMix(phrase,voice,rate,root):null;
   await playback.PlayAsync(()=>{if(mixed)microphone.Play(file!,(int)VolumeSlider.Value);else audio.Play(phrase,output,voice,volume,rate,root);},()=>mixed?microphone.IsPlaying:audio.IsPlaying,auto,key,fromHotkey,text=>StatusText.Text=phrase.Title+" · "+(mixed?"发送至游戏 · ":"仅本地试听 · ")+text);
  }catch(Exception ex){StatusText.Text="播放失败："+ex.Message;}
 }
 private void PlayRow(object sender,RoutedEventArgs e)=>Play((sender as FrameworkElement)?.DataContext as VoicePhrase);
 private void PlaySelected(object sender,RoutedEventArgs e)=>Play(Selected);
 private void StopPlayback(object sender,RoutedEventArgs e)=>Guard(()=>{playback.Stop();StatusText.Text="已停止播放并释放说话键。";});
 private void AddPhrase(object sender,RoutedEventArgs e){Commit();ShowType.SelectedIndex=0;var p=new VoicePhrase();phrases.Add(p);PhraseGrid.SelectedItem=p;PhraseGrid.ScrollIntoView(p);}
 private void DeletePhrase(object sender,RoutedEventArgs e){Commit();if(Selected is{} p)phrases.Remove(p);ApplyHotkeys();}
 private void ImportWav(object sender,RoutedEventArgs e){if(Selected is not{} p){StatusText.Text="请先选一条短句。";return;}var dialog=new OpenFileDialog{Filter="PCM WAV录音|*.wav",CheckFileExists=true};if(dialog.ShowDialog()!=true)return;Guard(()=>{Commit();p.Wav=VoiceBoardSettings.ImportWav(root,dialog.FileName);PhraseGrid.Items.Refresh();StatusText.Text="录音已复制到软件数据目录，移动原文件不会影响播放。";});}
 private void ClearWav(object sender,RoutedEventArgs e){Commit();if(Selected is{} p){p.Wav="";PhraseGrid.Items.Refresh();}}
 private void Save(){Commit();if(TalkMode.SelectedIndex==0&&!VoicePlaybackController.ParseTalkKey(TalkKeyBox.Text,out _))throw new InvalidOperationException("说话键格式无效，请使用字母、数字或F1～F11。");if(MicrophoneBox.SelectedItem is AudioDevice mic)settings.MicrophoneId=mic.Id;if(MixOutputBox.SelectedItem is AudioDevice target)settings.MixOutputId=target.Id;settings.MicrophoneVolume=(int)MicrophoneVolume.Value;settings.TransmitBoost=TransmitBoost.Value;settings.PushToTalk=TalkMode.SelectedIndex==0;settings.TalkKey=TalkKeyBox.Text.Trim().ToUpperInvariant();settings.Phrases=phrases.ToList();settings.Volume=(int)VolumeSlider.Value;settings.Rate=(int)RateSlider.Value;if(OutputBox.SelectedItem is SpeechChoice o)settings.OutputId=o.Id;if(VoiceBox.SelectedItem is SpeechChoice v)settings.VoiceId=v.Id;settings.Save(root);}
 private void SaveSettings(object sender,RoutedEventArgs e)=>Guard(()=>{Save();ApplyHotkeys();});
 private void ClearHotkeys(){if(source==null||source.IsDisposed){hotkeys.Clear();return;}foreach(int id in hotkeys.Keys)UnregisterHotKey(source.Handle,id);hotkeys.Clear();}
 private void ApplyHotkeys(){if(!ready||source==null)return;Commit();ClearHotkeys();if(HotkeysEnabled.IsChecked!=true){StatusText.Text="全局快捷键已暂停，仍可点击播放。";return;}var errors=new List<string>();var seen=new HashSet<(uint,uint)>();int id=0x4B00;foreach(var p in phrases){if(string.IsNullOrWhiteSpace(p.Hotkey))continue;if(!VoiceHotkey.Parse(p.Hotkey,out uint m,out uint k)){errors.Add(p.Title+"：快捷键格式错误");continue;}if(!seen.Add((m,k))){errors.Add(p.Title+"：快捷键重复");continue;}if(RegisterHotKey(source.Handle,++id,m|0x4000,k))hotkeys[id]=p;else errors.Add(p.Title+"：快捷键不可用（错误码 "+Marshal.GetLastWin32Error()+"）");}StatusText.Text=$"已启用 {hotkeys.Count} 个快捷键。"+(errors.Count>0?" "+string.Join("；",errors):" 修改后点“保存并应用”。");}
 private IntPtr Hook(IntPtr hwnd,int msg,IntPtr w,IntPtr l,ref bool handled){if(msg==0x0312&&hotkeys.TryGetValue(w.ToInt32(),out var p)){Play(p,true);handled=true;}return IntPtr.Zero;}
 internal int ActiveHotkeys=>hotkeys.Count;
 public void Dispose(){if(disposed)return;disposed=true;try{Save();}catch{}ClearHotkeys();if(source is {IsDisposed:false})source.RemoveHook(Hook);try{playback.Dispose();}finally{micTimer.Stop();microphone.Dispose();audio?.Dispose();audio=null;Close();}}
}
